import { useEffect, useMemo, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { ArrowDown, ArrowLeft, ArrowRight, ArrowUpRight, Bell, Boxes, Check, ChevronDown, CircleAlert, Heart, Headset, LayoutDashboard, LockKeyhole, LogOut, Menu, MessageCircle, Minus, Package, Pencil, Percent, Plus, Save, Search, Send, Settings, ShieldCheck, ShoppingBag, ShoppingCart, SlidersHorizontal, Store, Tag, Trash2, Truck, X } from 'lucide-react'
import { gsap } from 'gsap'
import { isSupabaseConfigured, supabaseAnonKey, supabaseConfigMessage, supabaseUrl } from './supabaseConfig'

type Category = string
type ProductVariant = { id: string; name: string; color: string; images: string[]; sizes: string[] }
type Product = { id: string; slug: string; name: string; category: Category; type: string; price: number; compareAtPrice?: number; promoActive?: boolean; stock?: number; image: string; image2: string; images?: string[]; colors: string[]; sizes: string[]; variants?: ProductVariant[]; featured?: boolean; newest?: boolean; description?: string }
type CartLine = { key: string; productId: string; size: string; color: string; qty: number }
const photo = (id: string, width = 900) => `https://images.unsplash.com/${id}?auto=format&fit=crop&w=${width}&q=82`
const load = <T,>(key: string, fallback: T): T => { try { return JSON.parse(localStorage.getItem(key) || 'null') ?? fallback } catch { return fallback } }
type StoreSettings = { brandName: string; announcement: string; currency: string; supportEmail: string; shippingNote: string; returnsNote: string }
const defaultSettings: StoreSettings = { brandName: 'KA7LA', announcement: 'NEW SEASON. NEW ENERGY. DISCOVER THE LATEST DROP.', currency: 'TND', supportEmail: '', shippingNote: 'Flat-rate delivery: 8 DT.', returnsNote: 'Returns policy is not configured.' }
let storeSettings: StoreSettings = load('ka7la-settings', defaultSettings)
if (storeSettings.shippingNote === 'Shipping is not configured.') storeSettings = { ...storeSettings, shippingNote: defaultSettings.shippingNote }
const money = (n: number) => `${storeSettings.currency || 'CUR'} ${n.toFixed(0)}`
const SHIPPING_FEE = 8
