  const nav: {name:AdminTab;icon:React.ReactNode}[]=[{name:'Overview',icon:<LayoutDashboard/>},{name:'Products',icon:<Package/>},{name:'Orders',icon:<ShoppingCart/>},{name:'Support',icon:<Headset/>},{name:'Discounts',icon:<Percent/>},{name:'Settings',icon:<Settings/>}]
