  const flash=(message:string)=>{setSavedMessage(message);window.setTimeout(()=>setSavedMessage(''),2600)}
  useEffect(()=>{let alive=true;const bootstrap=async()=>{const {supabase}=await import('./supabase');const [catalogResult,orderResult,discountResult,supportResult]=await Promise.all([supabase.from('products').select('*').order('created_at'),supabase.from('orders').select('*').order('created_at',{ascending:false}),supabase.from('discounts').select('*').order('created_at',{ascending:false}),supabase.from('support_tickets').select('*').order('created_at',{ascending:false})]);const firstError=[catalogResult.error,orderResult.error,discountResult.error,supportResult.error].find(Boolean);if(firstError){if(alive){flash(`Store data could not load: ${firstError.message}`);setDataBusy(false)}return}if(!alive)return;let remoteProducts=(catalogResult.data||[]).map(row=>productFromRow(row as unknown as ProductRow));if(!remoteProducts.length)remoteProducts=catalog;try{await saveCatalog(remoteProducts)}catch(error){flash(error instanceof Error?error.message:'Could not initialize the product catalog.')}const remoteOrders=(orderResult.data||[]).map(row=>orderFromRow(row as unknown as OrderRow));setOrders(remoteOrders.sort((a,b)=>b.createdAt.localeCompare(a.createdAt)));setDiscounts((discountResult.data||[]).map(row=>({id:row.id,code:row.code,amount:row.amount,active:row.active})));setSupportTickets((supportResult.data||[]) as SupportTicket[]);setDataBusy(false)};void bootstrap();return()=>{alive=false}},[])
  useEffect(()=>{setSettingsDraft(settings)},[settings])
