  const uploadVariantImages=async(index:number,files:FileList|null)=>{if(!editing||!files?.length)return;const target=productVariants(editing)[index];if(!target)return;const selected=Array.from(files);const valid=selected.filter(file=>['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)&&file.size<=8*1024*1024);if(valid.length!==selected.length)flash('Some files were skipped. Use JPG, PNG, WEBP, or AVIF images up to 8 MB each.');if(!valid.length)return;setImageUploading(true);try{const {supabase}=await import('./supabase');const uploaded=await Promise.all(valid.map(async file=>{const extension=file.type.split('/')[1].replace('jpeg','jpg');const path=`products/${Date.now()}-${crypto.randomUUID()}.${extension}`;const {data,error}=await supabase.storage.from('store-images').upload(path,file,{cacheControl:'3600',contentType:file.type,upsert:false});if(error)throw error;return supabase.storage.from('store-images').getPublicUrl(data.path).data.publicUrl}));setEditing(current=>{if(!current)return current;const variants=productVariants(current);const targetIndex=variants.findIndex(variant=>variant.id===target.id);if(targetIndex<0)return current;const next=variants.map((variant,i)=>i===targetIndex?{...variant,images:[...variant.images,...uploaded]}:variant);const images=[...new Set(next.flatMap(variant=>variant.images))];return {...current,variants:next,colors:next.map(variant=>variant.color),sizes:[...new Set(next.flatMap(variant=>variant.sizes))],images,image:images[0]||'',image2:images[1]||''}});flash(`Added ${uploaded.length} photo${uploaded.length===1?'':'s'} to ${target.name}. Save the product to publish.`)}catch(error){flash(error instanceof Error?error.message:'Could not upload the selected images.')}finally{setImageUploading(false)}}
  const removeVariantImage=(variantIndex:number,image:string)=>setEditing(current=>{if(!current)return current;const variants=productVariants(current).map((variant,index)=>index===variantIndex?{...variant,images:variant.images.filter(item=>item!==image)}:variant);const images=[...new Set(variants.flatMap(variant=>variant.images))];return {...current,variants,images,image:images[0]||'',image2:images[1]||''}})
  const persistProduct=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editing||productSaving)return;if(!productImages(editing).length){flash('Add at least one product image before saving.');return}if(editing.promoActive&&(!(Number(editing.compareAtPrice)>Number(editing.price)))){flash('Enter a compare-at price higher than the sale price to activate the promo.');return}const incompleteVariant=productVariants(editing).find(variant=>!variant.images.length||!variant.sizes.length);if(incompleteVariant){flash(`Add at least one photo and one size for ${incompleteVariant.name}.`);return}const baseSlug=editing.name.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/,'')||'piece';const exists=catalog.some(p=>p.id===editing.id);setProductSaving(true);try{const {supabase}=await import('./supabase');const {data:storedProducts,error:readError}=await supabase.from('products').select('id,slug');if(readError)throw readError;const slugTaken=[...catalog,...(storedProducts||[])].some(product=>product.id!==editing.id&&product.slug===baseSlug);const value={...editing,category:storefrontCategory(editing)||'Hoodie',slug:slugTaken?`${baseSlug}-${editing.id.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}`:baseSlug,price:Number(editing.price),compareAtPrice:editing.compareAtPrice?Number(editing.compareAtPrice):undefined,promoActive:!!editing.promoActive,stock:Math.max(0,Number(editing.stock)||0)};await saveCatalog(exists?catalog.map(p=>p.id===value.id?value:p):[value,...catalog]);setEditing(null);flash('Product saved.')}catch(error){const message=error instanceof Error?error.message:'Could not save product.';flash(/products_slug_key|duplicate key/i.test(message)?'A product already uses this URL name. Change the product name and try again.':message)}finally{setProductSaving(false)}}
  const removeProduct=async(p:Product)=>{if(!window.confirm(`Remove ${p.name} from the catalog?`))return;try{await deleteProduct(p.id);await saveCatalog(catalog.filter(item=>item.id!==p.id));flash('Product removed.')}catch(error){flash(error instanceof Error?error.message:'Could not remove product.')}}
  const updateTicketStatus=async(id:string,status:SupportTicket['status'])=>{const {supabase}=await import('./supabase');const {error}=await supabase.from('support_tickets').update({status}).eq('id',id);if(error){flash(error.message);return}setSupportTickets(current=>current.map(ticket=>ticket.id===id?{...ticket,status}:ticket));flash('Support ticket updated.')};const deleteTicket=async(ticket:SupportTicket)=>{if(!window.confirm(`Delete the support ticket from ${ticket.name}?`))return;const {supabase}=await import('./supabase');const {error}=await supabase.from('support_tickets').delete().eq('id',ticket.id);if(error){flash(error.message);return}setSupportTickets(current=>current.filter(item=>item.id!==ticket.id));flash('Support ticket deleted.')};const setOrderStatus=async(id:string,status:DemoOrder['status'])=>{const {supabase}=await import('./supabase');const {error}=await supabase.from('orders').update({status}).eq('id',id);if(error){flash(error.message);return}setOrders(current=>current.map(order=>order.id===id?{...order,status}:order));flash(`Order ${id} updated to ${status}.`)}
  const addDiscount=async()=>{const code=discountCode.trim().toUpperCase(),amount=Number(discountAmount);if(!code||!amount||amount<1||amount>90||discounts.some(d=>d.code===code))return;const {supabase}=await import('./supabase');const row={id:`d-${Date.now()}`,code,amount,active:true};const {error}=await supabase.from('discounts').insert(row);if(error){flash(error.message);return}setDiscounts([row,...discounts]);setDiscountCode('')}
